const pedir = async (url, ms) => {
  const control = new AbortController();
  const timer = setTimeout(() => control.abort(), ms);
  try {
    return await fetch(url, {
      signal: control.signal,
      headers: { 'User-Agent': 'Mozilla/5.0 (VestuarioDigital demo)' },
    });
  } finally {
    clearTimeout(timer);
  }
};

// Descarga la foto de Pexels y la devuelve como data URI (o null).
const bajarFoto = async (id, pagina) => {
  const aDataUri = async (res) => {
    const tipo = (res.headers.get('content-type') || '').split(';')[0];
    if (!res.ok || !tipo.startsWith('image/')) return null;
    const buf = Buffer.from(await res.arrayBuffer());
    return buf.length > 2000 ? 'data:' + tipo + ';base64,' + buf.toString('base64') : null;
  };

  // 1) Dirección directa de la imagen
  try {
    const url = 'https://images.pexels.com/photos/' + id + '/pexels-photo-' + id + '.jpeg?auto=compress&cs=tinysrgb&w=500';
    const dato = await aDataUri(await pedir(url, 20000));
    if (dato) return dato;
  } catch (e) { /* probamos la otra forma */ }

  // 2) Leer la página de la foto y tomar su imagen principal
  try {
    const res = await pedir('https://www.pexels.com/photo/' + pagina + '-' + id + '/', 20000);
    if (res.ok) {
      const html = await res.text();
      const m = html.match(/property="og:image"\s+content="([^"]+)"/) || html.match(/content="([^"]+)"\s+property="og:image"/);
      if (m) {
        const url = m[1].replace(/&amp;/g, '&').split('?')[0] + '?auto=compress&cs=tinysrgb&w=500';
        const dato = await aDataUri(await pedir(url, 20000));
        if (dato) return dato;
      }
    }
  } catch (e) { /* queda el dibujo */ }

  return null;
};

(async () => {
  const email = String(process.argv[2] || '').trim();

  if (!email) {
    console.log('Falta el correo. Uso: node --env-file=.env cargar_ropa_mujer.js correo@de-la-cuenta.com');
    process.exit(1);
  }

  let conn;

  try {
    conn = await mysql.createConnection({
      host: process.env.DB_HOST || 'localhost',
      user: process.env.DB_USER || 'root',
      password: process.env.DB_PASSWORD || '',
      database: process.env.DB_NAME || 'vestuario',
    });
  } catch (error) {
    console.log('No se pudo conectar a MySQL. ¿Está encendido en XAMPP?');
    console.log(error.message);
    process.exit(1);
  }

  const [users] = await conn.query('SELECT id, name, email FROM users WHERE LOWER(email) = LOWER(?)', [email]);

  if (users.length === 0) {
    console.log('No existe ninguna cuenta con el correo ' + email + '. Creala primero desde la app.');
    await conn.end();
    process.exit(1);
  }

  const user = users[0];
  const [existentes] = await conn.query('SELECT id, title FROM clothes WHERE userId = ?', [user.id]);
  const porTitulo = new Map(existentes.map((r) => [String(r.title).trim().toLowerCase(), r.id]));

  console.log('Cargando prendas en la cuenta de ' + (user.name || user.email) + '...');

  let nuevas = 0;
  let actualizadas = 0;
  let conFoto = 0;
  const sinFoto = [];
  const base = Date.now();

  for (let i = 0; i < PRENDAS.length; i += 1) {
    const p = PRENDAS[i];
    let imagen = p.imageUri;

    if (p.photoId) {
      process.stdout.write('  Foto: ' + p.title + '... ');
      const foto = await bajarFoto(p.photoId, p.photoPage);
      if (foto) {
        imagen = foto;
        conFoto += 1;
        console.log('ok');
      } else {
        sinFoto.push(p.title);
        console.log('no se pudo (queda el dibujo)');
      }
    }

    const id =
      porTitulo.get(p.title.toLowerCase()) ||
      (p.oldTitle ? porTitulo.get(p.oldTitle.toLowerCase()) : undefined);

    if (id) {
      // Ya existía: si conseguimos la foto real, la actualizamos.
      if (p.photoId && imagen !== p.imageUri) {
        await conn.query(
          'UPDATE clothes SET title = ?, category = ?, color = ?, season = ?, ocasion = ?, description = ?, imageUri = ? WHERE id = ?',
          [p.title, p.category, p.color, p.season, p.ocasion, p.description, imagen, id]
        );
        actualizadas += 1;
      }
      continue;
    }

    await conn.query(
      'INSERT INTO clothes (userId, title, category, color, season, ocasion, description, imageUri, createdAt) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)',
      [user.id, p.title, p.category, p.color, p.season, p.ocasion, p.description, imagen, new Date(base - (PRENDAS.length - i) * 1000).toISOString()]
    );
    nuevas += 1;
  }

  await conn.end();

  console.log('');
  console.log('Listo: ' + nuevas + ' prendas nuevas y ' + actualizadas + ' actualizadas con foto real.');
  console.log('Fotos reales descargadas: ' + conFoto + ' de ' + PRENDAS.filter((p) => p.photoId).length + '.');
  if (sinFoto.length) {
    console.log('Sin foto (quedó el dibujo): ' + sinFoto.join(', ') + '. Revisá la conexión a internet y volvé a ejecutarlo.');
  }
  console.log('Recargá la página de la app (F5) para verlas.');
})().catch((error) => {
  console.log('Ocurrió un error al cargar las prendas:', error.message);
  process.exit(1);
});
